B.aOP=s(["\u0628\u0633\u0645 \u0627\u0644\u0644\u0647 \u0627\u0644\u0631\u062d\u0645\u0646 \u0627\u0644\u0631\u062d\u064a\u0645","\u0625\u0646 \u0627\u0644\u062d\u0645\u062f \u0644\u0644\u0647\u060c \u0646\u062d\u0645\u062f\u0647 \u0648\u0646\u0633\u062a\u0639\u064a\u0646\u0647\u060c \u0648\u0646\u0633\u062a\u063a\u0641\u0631\u0647\u060c \u0648\u0646\u0639\u0648\u0630 \u0628\u0627\u0644\u0644\u0647 \u0645\u0646 \u0634\u0631\u0648\u0631 \u0623\u0646\u0641\u0633\u0646\u0627\u060c \u0648\u0633\u064a\u0626\u0627\u062a \u0623\u0639\u0645\u0627\u0644\u0646\u0627\u060c \u0645\u0646 \u064a\u0647\u062f\u0647 \u0627\u0644\u0644\u0647 \u0641\u0644\u0627 \u0645\u0636\u0644 \u0644\u0647\u060c \u0648\u0645\u0646 \u064a\u0636\u0644\u0644 \u0641\u0644\u0627 \u0647\u0627\u062f\u064a \u0644\u0647\u060c \u0648\u0623\u0634\u0647\u062f \u0623\u0646 \u0644\u0627 \u0625\u0644\u0647 \u0625\u0644\u0627 \u0627\u0644\u0644\u0647 \u0648\u062d\u062f\u0647 \u0644\u0627 \u0634\u0631\u064a\u0643 \u0644\u0647\u060c \u0648\u0623\u0634\u0647\u062f \u0623\u0646 \u0645\u062d\u0645\u062f\u064b\u0627 \u0639\u0628\u062f\u0647 \u0648\u0631\u0633\u0648\u0644\u0647.","\ufd3f\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u062d\u064e\u0642\u0651\u064e \u062a\u064f\u0642\u064e\u0627\u062a\u0650\u0647\u0650 \u0648\u064e\u0644\u064e\u0627 \u062a\u064e\u0645\u064f\u0648\u062a\u064f\u0646\u0651\u064e \u0625\u0650\u0644\u0651\u064e\u0627 \u0648\u064e\u0623\u064e\u0646\u062a\u064f\u0645 \u0645\u0651\u064f\u0633\u0644\u0650\u0645\u064f\u0648\u0646\u064e\ufd3e - \u0633\u0648\u0631\u0629 \u0622\u0644 \u0639\u0645\u0631\u0627\u0646","\ufd3f\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0646\u0651\u064e\u0627\u0633\u064f \u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0631\u064e\u0628\u0651\u064e\u0643\u064f\u0645\u064f \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062e\u064e\u0644\u064e\u0642\u064e\u0643\u064f\u0645 \u0645\u0651\u0650\u0646 \u0646\u0651\u064e\u0641\u0633\u064d \u0648\u064e\u0627\u062d\u0650\u062f\u064e\u0629\u064d \u0648\u064e\u062e\u064e\u0644\u064e\u0642\u064e \u0645\u0650\u0646\u0647\u064e\u0627 \u0632\u064e\u0648\u062c\u064e\u0647\u064e\u0627 \u0648\u064e\u0628\u064e\u062b\u0651\u064e \u0645\u0650\u0646\u0647\u064f\u0645\u064e\u0627 \u0631\u0650\u062c\u064e\u0627\u0644\u064b\u0627 \u0643\u064e\u062b\u0650\u064a\u0631\u064b\u0627 \u0648\u064e\u0646\u0650\u0633\u064e\u0627\u0621\u064b \u0648\u064e\u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0627\u0644\u0651\u064e\u0630\u0650\u064a \u062a\u064e\u0633\u064e\u0627\u0621\u064e\u0644\u064f\u0648\u0646\u064e \u0628\u0650\u0647\u0650 \u0648\u064e\u0627\u0644\u0623\u064e\u0631\u062d\u064e\u0627\u0645\u064e \u0625\u0650\u0646\u0651\u064e \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0643\u064e\u0627\u0646\u064e \u0639\u064e\u0644\u064e\u064a\u0643\u064f\u0645 \u0631\u064e\u0642\u0650\u064a\u0628\u064b\u0627\ufd3e - \u0633\u0648\u0631\u0629 \u0627\u0644\u0646\u0633\u0627\u0621","\ufd3f\u064a\u064e\u0627 \u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0642\u064f\u0648\u0644\u064f\u0648\u0627 \u0642\u064e\u0648\u0644\u064b\u0627 \u0633\u064e\u062f\u0650\u064a\u062f\u064b\u0627 \u06dd \u064a\u064f\u0635\u0644\u0650\u062d \u0644\u064e\u0643\u064f\u0645 \u0623\u064e\u0639\u0645\u064e\u0627\u0644\u064e\u0643\u064f\u0645 \u0648\u064e\u064a\u064e\u063a\u0641\u0650\u0631 \u0644\u064e\u0643\u064f\u0645 \u0630\u064f\u0646\u064f\u0648\u0628\u064e\u0643\u064f\u0645 \u0648\u064e\u0645\u064e\u0646 \u064a\u064f\u0637\u0650\u0639\u0650 \u0627\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f \u0641\u064e\u0642\u064e\u062f \u0641\u064e\u0627\u0632\u064e \u0641\u064e\u0648\u0632\u064b\u0627 \u0639\u064e\u0638\u0650\u064a\u0645\u064b\u0627\ufd3e - \u0633\u0648\u0631\u0629 \u0627\u0644\u0623\u062d\u0632\u0627\u0628","\u064a\u0627 \u0631\u0628 \u0644\u0643 \u0627\u0644\u062d\u0645\u062f \u0643\u0645\u0627 \u064a\u0646\u0628\u063a\u064a \u0644\u062c\u0644\u0627\u0644 \u0648\u062c\u0647\u0643 \u0648\u0639\u0638\u064a\u0645 \u0633\u0644\u0637\u0627\u0646\u0643\u060c \u0648\u0644\u0643 \u0627\u0644\u062d\u0645\u062f \u062d\u062a\u0649 \u062a\u0631\u0636\u0649\u060c \u0648\u0644\u0643 \u0627\u0644\u062d\u0645\u062f \u0625\u0630\u0627 \u0631\u0636\u064a\u062a\u060c \u0648\u0644\u0643 \u0627\u0644\u062d\u0645\u062f \u0628\u0639\u062f \u0627\u0644\u0631\u0636\u0649\u060c \u0623\u0645\u0627 \u0628\u0639\u062f:"],t.s)
